# -*- coding: utf-8 -*-
# MT2009_PLUS_RUNY_WYKUWANIA_V1 - Runy Wykuwania (79605-79659) in the client's data. One list: tools/runy/runy_items.json
# (GENERATED by tools/runy/gen_runy.py together with the server's runy_wykuwania.sql - keep them equal):
#
#   gamedata/item_proto (dbdata)     55 records: ITEM_QUEST (18) / 0, stack 200, flags 4 (stackable); antiflags 221312
#                                    (1*-4*: no drop / give / PK drop / private shop / storeroom) or 16512 (5*: no drop /
#                                    PK drop); name and locale name the Polish name ("1* Runa Wykuwania Pasow" ..
#                                    "5* Runa Wyk. Prz. d. Zw.")
#   gamedata/item_list.txt           <vnum>\tETC\ticon/item/<79605..79609 by grade>.tga (GF 26.1.11's lines; the icons
#                                    travel in client-2.0.30/root/icon/item - the root pack takes them)
#   locale/pl/itemdesc.txt (dbdata)  <vnum>\t<name>\t<the pl-wiki's description + how to use / upgrade it>
# A record or line that is there with other content is rewritten (these vnums are the runes'); idempotent.
#
#   docker run --rm -v /opt/metin2:/opt/metin2 m2pack-lzo python3 \
#     <repo>/client-patches/client-2.0.30/tools/runy/patch_runy_client.py <item_proto|item_list.txt|itemdesc.txt> ... [--check]
import io
import json
import os
import struct
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, '/opt/metin2/cache/tcm/tz')
sys.path.insert(0, os.path.join(HERE, '..', 'monstercard'))
import patch_monstercard_client as base  # noqa: E402

REPO = os.path.normpath(os.path.join(HERE, '..', '..', '..', '..'))
ITEMS_JSON = os.path.join(REPO, 'tools', 'runy', 'runy_items.json')
COUNT = 55
FIRST, LAST = 79605, 79659


def data():
    with io.open(ITEMS_JSON, encoding='utf-8') as f:
        d = json.load(f)
    assert len(d['items']) == COUNT and len(d['item_list']) == COUNT and len(d['itemdesc']) == COUNT
    assert [i['vnum'] for i in d['items']] == list(range(FIRST, LAST + 1))
    return d


def item_record(it):
    pl = it['locale_name']
    assert len(pl.encode('cp1250')) < 33, pl
    r = bytearray(base.RECORD)
    struct.pack_into('<II', r, 0, it['vnum'], 0)
    r[8:41] = base.fixed(pl, 33)
    r[41:74] = base.fixed(pl, 33)
    struct.pack_into('<BBBB', r, 74, it['type'], it['subtype'], 0, 1)                    # type, subtype, weight, size
    struct.pack_into('<IIIII', r, 78, it['stack'], it['antiflag'], it['flag'], 0, 0)    # stack, anti, flags, wear, immune
    struct.pack_into('<qq', r, 98, it['gold'], it['shop_buy_price'])                     # buy, sell
    struct.pack_into('<BiBi', r, 114, 0, 0, 0, 0)
    struct.pack_into('<6i', r, 139, it['value0'], it['value1'], 0, 0, 0, 0)
    return bytes(r)


def records(b):
    import m2pack
    assert b[:4] == b'MIPX'
    ver, stride, cnt, size = struct.unpack_from('<IIII', b, 4)
    assert stride == base.RECORD, stride
    raw = m2pack.mcoz_decode(b[20:], base.ITEM_KEY)
    return ver, dict((struct.unpack_from('<I', raw, i * base.RECORD)[0], raw[i * base.RECORD:(i + 1) * base.RECORD])
                     for i in range(cnt))


def want_records():
    return dict((it['vnum'], item_record(it)) for it in data()['items'])


def item_proto(b):
    import m2pack
    ver, recs = records(b)
    changed = 0
    for v, r in sorted(want_records().items()):
        if recs.get(v) != r:
            recs[v] = r
            changed += 1
    if not changed:
        return b, 0
    out = b''.join(recs[v] for v in sorted(recs))
    blob = m2pack.mcoz_encode(out, base.ITEM_KEY)
    return b'MIPX' + struct.pack('<IIII', ver, base.RECORD, len(recs), len(blob)) + blob, changed


def list_rows():
    d = data()
    return [d['item_list'][k] for k in sorted(d['item_list'], key=int)]


def desc_rows():
    d = data()
    rows = [d['itemdesc'][k] for k in sorted(d['itemdesc'], key=int)]
    for r in rows:
        assert '\r' not in r and '\n' not in r and r.count('\t') == 2, r
    return rows


def item_list(b):
    return base.set_rows(b, list_rows())


def itemdesc(b):
    return base.set_rows(b, desc_rows())


def icons():
    """the GF icons the item_list lines name -> their file in client-2.0.30/root"""
    names = sorted(set(r.split('\t')[2] for r in list_rows()))
    return dict((n, os.path.join(REPO, 'client-patches', 'client-2.0.30', 'root', n)) for n in names)


# in-pack name -> function; the pack of each
JOBS = {'gamedata/item_list.txt': item_list, 'gamedata/item_proto': item_proto, 'locale/pl/itemdesc.txt': itemdesc}
PACK_OF = {'gamedata/item_list.txt': 'gamedata', 'gamedata/item_proto': 'dbdata', 'locale/pl/itemdesc.txt': 'dbdata'}
BY_FILE = dict((os.path.basename(k), f) for k, f in JOBS.items())


def main():
    args = [a for a in sys.argv[1:] if a != '--check']
    check = '--check' in sys.argv
    if not args:
        raise SystemExit('usage: patch_runy_client.py <item_list.txt|item_proto|itemdesc.txt> ... [--check]')
    for path in args:
        fn = BY_FILE.get(os.path.basename(path))
        if fn is None:
            raise SystemExit('%s: not one of %s' % (path, sorted(BY_FILE)))
        b = open(path, 'rb').read()
        nb, n = fn(b)
        if n and not check:
            open(path, 'wb').write(nb)
        print('%s: %d new/changed%s' % (os.path.basename(path), n, ' (check only)' if check else ''))


if __name__ == '__main__':
    main()
